var msg = $input.first().json.chatInput || $input.first().json.text || '';

var brief = {
  raw_input: msg,
  product_name: '',
  description: '',
  url: '',
  tone: 'professional',
  formats: ['linkedin', 'email', 'blog', 'ads']
};

var urlMatch = msg.match(/https?:\/\/[^\s]+/);
if (urlMatch) {
  brief.url = urlMatch[0];
  msg = msg.replace(urlMatch[0], '').trim();
}

var toneKeywords = ['professional', 'conversational', 'bold', 'casual', 'formal', 'playful', 'authoritative', 'friendly', 'technical'];
var lower = msg.toLowerCase();
for (var i = 0; i < toneKeywords.length; i++) {
  if (lower.indexOf(toneKeywords[i] + ' tone') >= 0 || lower.indexOf('tone: ' + toneKeywords[i]) >= 0) {
    brief.tone = toneKeywords[i];
    break;
  }
}

var cleaned = msg
  .replace(/tone:?\s*\w+/i, '')
  .replace(/^(write content for|create content for|launch content for|promote|create a launch for)\s*/i, '')
  .replace(/^(can you|please|could you)\s*/i, '')
  .replace(/[?.!]$/g, '')
  .trim();

var parts = cleaned.split(/\s*[-—:]\s*/);
if (parts.length >= 2) {
  brief.product_name = parts[0].trim();
  brief.description = parts.slice(1).join(' ').trim();
} else {
  brief.product_name = cleaned;
  brief.description = '';
}

if (!brief.product_name || brief.product_name.length < 2) {
  brief.product_name = cleaned || msg;
}

return [{ json: brief }];

var items = $input.all();
var productName = '';
try { productName = $('Normalize Input').item.json.product_name.toLowerCase(); } catch(e) { productName = ''; }
var brief = {};
try { brief = $('Normalize Input').item.json; } catch(e) { brief = { product_name: productName, tone: 'professional' }; }

var matched = [];
var allProducts = [];

for (var i = 0; i < items.length; i++) {
  var row = items[i].json;
  var name = (row['Product Name'] || row['product_name'] || '').toLowerCase();
  var text = Object.keys(row).map(function(k) { return k + ': ' + row[k]; }).join('\n');
  allProducts.push(text);
  if (name.indexOf(productName) >= 0 || productName.indexOf(name) >= 0) {
    matched.push(text);
  }
}

var productData = '';
if (matched.length > 0) {
  productData = matched.join('\n\n');
} else if (allProducts.length > 0) {
  productData = 'No exact match for "' + productName + '". All products:\n\n' + allProducts.join('\n\n');
} else {
  productData = 'No product catalog loaded. Using the description from user input only.';
}

if (brief.description) {
  productData = 'USER DESCRIPTION: ' + brief.description + '\n\nCATALOG DATA:\n' + productData;
}

return [{ json: { product_name: brief.product_name, product_data: productData, tone: brief.tone, url: brief.url, formats: brief.formats } }];

