var item = $input.first().json;
var raw = item.response || item.output || item.text || '';
if (typeof raw === 'object') raw = JSON.stringify(raw);
var revised = {};
try {
  var m = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  var js = m ? m[1].trim() : raw.substring(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
  revised = JSON.parse(js);
} catch(e) {
  revised = $('Parse Draft').item.json.draft;
  revised.changelog = ['Revision parsing failed — returning original draft'];
}
return [{ json: { final_content: revised, was_revised: true, changelog: revised.changelog || [] } }];

var data = $input.first().json;
var content = data.final_content;
var wasRevised = data.was_revised;
var changelog = data.changelog || [];

var draft = {};
try { draft = $('Parse Draft').item.json.draft; } catch(e) { draft = {}; }
var review = {};
try { review = $('Parse Review').item.json.review; } catch(e) { review = {}; }
var strategy = {};
try { strategy = $('Parse Strategy').item.json.strategy; } catch(e) { strategy = {}; }
var product = '';
try { product = $('Find Product').item.json.product_name; } catch(e) { product = 'Unknown'; }

var d = '=';
var div = '\n' + d.repeat(50) + '\n';

var out = d.repeat(50);
out += '\n  GTM CONTENT SUITE — ' + product.toUpperCase();
out += '\n  Generated: ' + new Date().toLocaleDateString('en-US', {month:'long', day:'numeric', year:'numeric'});
out += '\n  Status: ' + (wasRevised ? 'Revised after editorial review' : 'Passed editorial review');
out += '\n  Review Score: ' + (review.overall_score || '?') + '/10';
out += '\n' + d.repeat(50);

if (strategy.value_proposition) {
  out += div + 'VALUE PROPOSITION\n' + strategy.value_proposition;
}
if (strategy.target_audience && strategy.target_audience.primary) {
  out += '\n\nTARGET: ' + strategy.target_audience.primary;
}
if (strategy.tone) {
  out += '\nTONE: ' + strategy.tone;
}

out += div + 'LINKEDIN POST';
out += '\n\n' + (content.linkedin_post || 'Not generated');

out += div + 'EMAIL';
if (content.email) {
  out += '\nSubject: ' + (content.email.subject_line || '');
  out += '\nPreview: ' + (content.email.preview_text || '');
  out += '\n\n' + (content.email.body || '');
} else {
  out += '\nNot generated';
}

out += div + 'BLOG DRAFT';
out += '\n\n' + (content.blog_draft || 'Not generated');

out += div + 'AD COPY';
if (content.ad_copy) {
  if (content.ad_copy.headline_variations) out += '\nHeadlines:\n  ' + content.ad_copy.headline_variations.join('\n  ');
  if (content.ad_copy.body_variations) out += '\n\nBody:\n  ' + content.ad_copy.body_variations.join('\n  ');
  if (content.ad_copy.cta_variations) out += '\n\nCTAs:\n  ' + content.ad_copy.cta_variations.join('\n  ');
} else {
  out += '\nNot generated';
}

if (review.dimensions) {
  out += div + 'EDITORIAL REVIEW';
  var dims = ['clarity', 'positioning', 'factual_risk', 'channel_fit', 'conversion_strength'];
  for (var i = 0; i < dims.length; i++) {
    var dim = review.dimensions[dims[i]];
    if (dim) out += '\n  ' + dims[i].replace('_', ' ').toUpperCase() + ': ' + dim.score + '/10 — ' + dim.feedback;
  }
}

if (review.per_format) {
  out += '\n\nPer-format notes:';
  var fmts = ['linkedin', 'email', 'blog', 'ads'];
  for (var f = 0; f < fmts.length; f++) {
    if (review.per_format[fmts[f]]) out += '\n  ' + fmts[f].toUpperCase() + ': ' + review.per_format[fmts[f]];
  }
}

if (wasRevised && changelog.length > 0) {
  out += div + 'CHANGELOG';
  for (var c = 0; c < changelog.length; c++) {
    out += '\n  ' + (c+1) + '. ' + changelog[c];
  }
}

out += '\n\n' + d.repeat(50);

return [{ json: { output: out } }];
